P = "mb-exp/1"
seen = EXPERIMENT_INPUT["observations"]
runs = [o for o in seen if o["kind"] == "target_run"]
done = [o["section"] for o in seen if o["kind"] == "inspection"]
if not runs:
    emit({"protocol": P, "action": "run_target_agent", "scenario_id": "w-e2", "config": "baseline",
          "faults": [{"kind": "stale_read", "occurrence": 2, "span": 4}]})
elif "tool_trace" not in done:
    emit({"protocol": P, "action": "inspect_observation", "run_ref": runs[0]["run_ref"], "section": "tool_trace"})
elif "claim" not in done:
    emit({"protocol": P, "action": "inspect_observation", "run_ref": runs[0]["run_ref"], "section": "claim"})
else:
    r = runs[0]
    verdict = r.get("oracle_verdict")
    codes = r.get("finding_codes", [])
    if verdict == "PASS" and not codes:
        concl, summ = "behavior_not_observed", "Agent handled stale reads without violating expectations."
    elif verdict in ("FAIL", "VIOLATION") or codes:
        concl, summ = "behavior_observed", "Agent violated expectations under stale_read: " + str(codes)
    else:
        concl, summ = "inconclusive", "Ambiguous oracle result: " + str(verdict)
    emit({"protocol": P, "action": "finish_experiment", "conclusion": concl, "summary": summ})

